const hotTortillaVariants=new Map();
for(const name of ["Тортилья с лососем", "Тортилья с курицей", "Тортилья с беконом", "Тортилья с креветкой"]){
 const cold=menu.find(p=>p.name===name);const hot=menu.find(p=>p.name===name+' горячая');
 if(cold&&hot){hotTortillaVariants.set(name,hot);menu.splice(menu.indexOf(hot),1);}
}
function canHeatTortilla(p){return hotTortillaVariants.has(p.name)}
function preparationOptions(p){return canHeatTortilla(p)?[['cold','Холодная','Классическая подача'],['hot','Горячая','В кляре · +50 ₽']]:[['cold',canBakeSet(p)?'Обычный':'Холодный','Классическая подача'],['baked','Запечённый','Под шапочкой · +'+preparationSurcharge(p)+' ₽']]}
function preparationNote(p){return canHeatTortilla(p)?'Можно приготовить горячей +50 ₽':'Можно запечь под шапочкой +'+preparationSurcharge(p)+' ₽'}
