const classicDefinitions=[["salmon", "Лосось", "Классика с лососем", "Рис, нори, лосось"], ["eel", "Угорь", "Классика с угрем", "Рис, нори, угорь жареный в соусе"], ["shrimp", "Креветка", "Классика с креветкой", "Рис, нори, креветка"], ["crab", "Краб", "Классика с крабом", "Рис, нори, краб"], ["chicken", "Курица", "Классика с курицей", "Рис, нори, курица копченая"], ["cucumber", "Огурец", "Классика с огурцом", "Рис, нори, огурец"]];
const classicVariants=classicDefinitions.map(([key,label,name,ingredients])=>{
 const aliases={};
 const item=menu.find(p=>p.name===(aliases[name]||name));
 if(!item||!Number.isFinite(item.price))throw new Error('Не найдена классика: '+name);
 return {key,label,item,ingredients:item.ingredients||ingredients};
});
const classicGroup={...classicVariants[0].item,id:Math.max(...menu.map(p=>p.id))+1,name:'Роллы классика',classicGroup:true,price:Math.min(...classicVariants.map(v=>v.item.price)),desc:'6 начинок · 8 шт',weight:'8 шт',ingredients:''};
const classicInsertion=menu.findIndex(p=>classicVariants.some(v=>v.item===p));
for(const variant of classicVariants)menu.splice(menu.indexOf(variant.item),1);
menu.splice(classicInsertion,0,classicGroup);
function createClassicChoice(){
 const node=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el};
 const wrap=node('div','classic-choice');
 const media=node('div','cc-media');const photo=node('div','cc-photo');const caption=node('p','cc-photo-caption');media.append(photo,caption);
 const info=node('div','cc-info');const heading=node('h2','','Роллы классика');heading.id='dishHeading';const subtitle=node('p','cc-subtitle');
 const fillings=node('fieldset','cc-fieldset');fillings.append(node('legend','','Выберите начинку'));
 const fillingGrid=node('div','cc-fillings');fillings.append(fillingGrid);
 const preparation=node('fieldset','cc-fieldset');preparation.append(node('legend','','Как приготовить?'));
 const prepGrid=node('div','cc-preparation');preparation.append(prepGrid);
 const composition=node('div','cc-composition');composition.append(node('h3','','Состав'));const ingredients=node('p');composition.append(ingredients);
 const total=node('div','cc-total');total.setAttribute('aria-live','polite');const totalLeft=node('div');totalLeft.append(node('span','cc-total-label','Итого за 8 шт.'));const price=node('strong','cc-price');totalLeft.append(price);const summary=node('p','cc-summary');total.append(totalLeft,summary);
 const call=node('a','cc-call','Позвонить и заказать');call.href='tel:+79632375357';
 info.append(heading,subtitle,fillings,preparation,composition,total,call);wrap.append(media,info);
 let selected=classicVariants[0],baked=false;
 const fillingButtons=[],prepButtons=[];
 function update(){
  const amount=selected.item.price+(baked?50:0);
  subtitle.textContent=selected.item.name+' · '+(baked?'запечённые':'холодные');
  photo.innerHTML=dishPhoto(selected.item);
  caption.textContent=baked?'На фото — холодный вариант':'';caption.hidden=!baked;
  ingredients.textContent=selected.ingredients+(baked?'; соус для запекания роллов':'');
  price.textContent=amount+' ₽';summary.textContent=selected.label+' · '+(baked?'запечённые':'холодные');
  fillingButtons.forEach(({button,variant})=>button.setAttribute('aria-pressed',String(variant===selected)));
  prepButtons.forEach(({button,isBaked,amountNode})=>{button.setAttribute('aria-pressed',String(isBaked===baked));amountNode.textContent=(selected.item.price+(isBaked?50:0))+' ₽'});
 }
 for(const variant of classicVariants){const button=node('button','cc-filling');button.type='button';button.append(node('span','',variant.label),node('strong','',variant.item.price+' ₽'));button.addEventListener('click',()=>{selected=variant;update()});fillingButtons.push({button,variant});fillingGrid.append(button)}
 for(const isBaked of [false,true]){const button=node('button','cc-prep');button.type='button';const amountNode=node('strong','cc-option-price');button.append(node('span','',isBaked?'Запечённые':'Холодные'),node('small','',isBaked?'Под шапочкой · +50 ₽':'Классическая подача'),amountNode);button.addEventListener('click',()=>{baked=isBaked;update()});prepButtons.push({button,isBaked,amountNode});prepGrid.append(button)}
 update();return wrap;
}

