function dishPhoto(p,card=false){if(p.name==="Шаурма классика")return `<span class="food-photo food-photo-real" role="img" aria-label="${p.name}"><img src="${shawarmaClassicData}" alt="${p.name}" loading="lazy" decoding="async"></span>`;if(p.classicGroup)return dishPhoto(classicVariants[0].item,card);if(p.name==='Сет Калифорния'&&p.cat==='Сеты')return `<span class="food-photo food-photo-real" role="img" aria-label="${p.name}"><img src="/api/catalog-photo/set-california?v=20261021" alt="${p.name}" loading="lazy" decoding="async"></span>`;const realPhoto=catalogRealPhotos[p.name];if(realPhoto)return `<span class="food-photo food-photo-real" role="img" aria-label="${p.name}"><img src="/api/catalog-photo/${realPhoto}?v=20261028-pizza5" alt="${p.name}" loading="lazy" decoding="async"></span>`;const fried=friedPhotoMarkup(p);if(fried)return fried;const c=photoCrops[p.id-1];if(!c)return `<span class="food-photo food-placeholder" role="img" aria-label="Фото ${p.name} готовится"><span class="fallback">Фото скоро</span></span>`;const d=photoDims[c[0]];return `<span class="food-photo" role="img" aria-label="${p.name}"><span class="fallback">${p.pic}</span><svg viewBox="${c[1]} ${c[2]} ${c[3]} ${c[4]}" preserveAspectRatio="${(card&&p.cat!=='Пицца')||(!card&&rollCats.includes(p.cat))?'xMidYMid slice':'xMidYMid meet'}" aria-hidden="true"><image href="${photoSources[c[0]]}" width="${d[0]}" height="${d[1]}"/>${c[0]==='klassika'?'<rect x="525" y="140" width="140" height="45" fill="#111"/>':''}</svg></span>`}let current='Пицца';const cats=['Все меню','Пицца','Роллы','Сеты','Шаурма','Салаты','Фритюр','Напитки'];const rollCats=['Сеты','Холодные роллы','Роллы классика'];function matchesTab(p){if(current==='Все меню')return true;if(current==='Роллы')return rollCats.includes(p.cat)&&p.cat!=='Сеты';return p.cat===current}function renderFilters(){filters.innerHTML=cats.map(c=>`<button type="button" role="tab" aria-selected="${c===current}" class="${c===current?'active':''}" onclick="filterCat('${c}')">${c}</button>`).join('')}function filterCat(c){current=c;renderFilters();renderProducts()}function money(n){return n==null?'Цена уточняется':`${Number(n).toLocaleString('ru-RU')} ₽`}function dishPrices(p){if(p.classicGroup)return '<span class="price">от '+money(p.price)+'</span>';if(!p.prices)return '<span class="price">'+money(p.price)+'</span>';return '<div class="pizza-size-prices">'+Object.entries(p.prices).map(([size,price])=>'<span><b>'+size+'</b> · '+money(price)+'</span>').join('')+'</div>'}function detailPrices(p){return p.prices?'<span class="pizza-modal-prices">'+Object.entries(p.prices).map(([size,price])=>'<span>'+size+' — '+money(price)+'</span>').join('')+'</span>':money(p.price)}const bakeableRollNames=new Set(["Филадельфия с сыром", "Филадельфия с огурцом", "Классика с угрем", "Классика с огурцом", "Классика с лососем", "Классика с курицей", "Классика с крабом", "Классика с креветкой", "Канада", "Ролл чиз", "Дракон", "Ролл Грин лосось", "Ролл Грин бекон", "Гурман", "Крем ролл с креветкой", "Ролл бекон", "Калифорния с лососем", "Калифорния краб", "Калифорния с креветкой"]);
const rollBakeSurcharge=50;
const setBakeSurcharge=350;
function canBakeSet(p){return p.cat==='Сеты'&&setPreparationVariants.has(p.name)&&Number.isFinite(p.price)}
function canChoosePreparation(p){return canHeatTortilla(p)||canBakeRoll(p)||canBakeSet(p)}
function preparationSurcharge(p){return canBakeSet(p)?(p.name==='Сет Калифорния'?setBakeSurcharge:150):rollBakeSurcharge}
function ordinaryPreparationLabel(p){return canHeatTortilla(p)?'холодная':canBakeSet(p)?'обычный':'холодный'}
function canBakeRoll(p){return ['Холодные роллы','Роллы классика'].includes(p.cat)&&bakeableRollNames.has(p.name)&&Number.isFinite(p.price)}
