function rollPreparationMarkup(p){return `<fieldset class="rp-roll-preparation"><legend>Как приготовить</legend>${preparationOptions(p).map(([value,title,subtitle])=>`<label class="rp-roll-option"><input type="radio" name="roll-preparation" value="${value}" ${value==='cold'?'checked':''} onchange="updateRollPreparation(${p.id},this.value)"><span><b>${title}</b><small>${subtitle}</small></span><strong>${money(rollPreparationPrice(p,value!=='cold'))}</strong></label>`).join('')}</fieldset><div class="rp-roll-total" aria-live="polite"><span>Итого</span><strong id="rollPreparationTotal">${money(p.price)}</strong></div><p class="rp-roll-summary" id="rollPreparationSummary">${p.name} · ${ordinaryPreparationLabel(p)}</p><a class="phoneOrder rp-roll-call" href="tel:+79632375357">Позвонить и заказать</a>`}
function updateRollPreparation(id,value){const p=menu.find(item=>item.id===id);if(!p||!canChoosePreparation(p))return;const baked=value!=='cold';document.getElementById('rollPreparationTotal').textContent=money(rollPreparationPrice(p,baked));document.getElementById('rollPreparationSummary').textContent=p.name+' · '+selectedPreparationLabel(p,baked);const composition=document.getElementById('dishComposition');if(canHeatTortilla(p)){const selected=baked?hotTortillaVariants.get(p.name):p;const media=dishContent.querySelector('.dishPhoto');if(media)media.innerHTML=dishPhoto(selected);if(composition)composition.textContent=selected.ingredients||'Состав уточняется';}if(composition&&canBakeSet(p)){composition.textContent=(baked?setPreparationVariants.get(p.name).ingredients:p.ingredients)||'Состав уточняется'}if(composition&&canBakeRoll(p)){composition.textContent=p.ingredients?(p.ingredients+(baked?'; соус для запекания роллов':'')):'Состав уточняется'}}
function renderProducts(){products.innerHTML=menu.filter(matchesTab).map(p=>`<article class="product ${p.classicGroup?'classic-group-card':''} ${rollCats.includes(p.cat)?'roll-product':''}"><button class="productOpen" type="button" onclick="openDish(${p.id})" aria-label="Подробнее: ${p.name}"><div class="pic">${dishPhoto(p,true)}</div><div class="productBody"><small>${p.cat}${p.weight?' · '+p.weight:''}</small><h3>${p.name}</h3>${p.classicGroup?'<span class="classic-fillings-badge">6 начинок</span>':''}${canChoosePreparation(p)?`<p class="rp-roll-bake-note">${preparationNote(p)}</p>`:''}</div></button><div class="priceRow">${dishPrices(p)}<button type="button" class="add" onclick="openDish(${p.id})">Подробнее</button></div></article>`).join('');if(!products.innerHTML&&current==='Напитки'){products.innerHTML='<p class="rp-drinks-info">Ассортимент напитков можно уточнить по телефону <a href="tel:+79632375357">+7 963 237-53-57</a>.</p>';}}let previousFocus;function openDish(id){const p=menu.find(x=>x.id===id);if(!p)return;if(p.classicGroup){previousFocus=document.activeElement;dishContent.replaceChildren(createClassicChoice());dishModal.classList.add('open');dishShade.classList.add('open');document.body.classList.add('dishLocked');dishModal.querySelector('.dishClose').focus();return;}previousFocus=document.activeElement;dishContent.innerHTML=`<div class="dishPhoto ${p.cat==='Пицца'?'dishPhotoPizza':rollCats.includes(p.cat)?'dishPhotoRoll':''}">${dishPhoto(p)}</div><div class="dishInfo"><small>${p.cat}${p.weight?' · '+p.weight:''}</small><h2 id="dishHeading">${p.name}</h2>${p.cat==='Фритюр'?'':`<h3>Состав</h3><p id="dishComposition">${p.ingredients||'Состав уточняется'}</p>`}${canChoosePreparation(p)?rollPreparationMarkup(p):`<div class="dishActions"><strong>${detailPrices(p)}</strong><a class="phoneOrder" href="tel:+79632375357">Позвонить и заказать</a></div>`}</div>`;dishModal.classList.add('open');dishShade.classList.add('open');document.body.classList.add('dishLocked');dishModal.querySelector('.dishClose').focus()}function closeDish(){dishModal.classList.remove('open');dishShade.classList.remove('open');document.body.classList.remove('dishLocked');previousFocus?.focus()}document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dishModal.classList.contains('open'))closeDish()});renderFilters();renderProducts();





